import{_ as r,o as s,c as n,ah as d}from"./chunks/framework.Cma4l5FK.js";const l="/projects/xArm1s/en/latest/assets/image1.PkdVrI_h.webp",h="/projects/xArm1s/en/latest/assets/image2.Ck4UJgjd.webp",c="/projects/xArm1s/en/latest/assets/image1.Bh0kDVd9.webp",m="/projects/xArm1s/en/latest/assets/image2.Cr9U72OQ.webp",g="/projects/xArm1s/en/latest/assets/image3.Cn3aaX80.webp",p="/projects/xArm1s/en/latest/assets/image1.BCu8cmJi.webp",u="/projects/xArm1s/en/latest/assets/image1.BJQBfmdZ.webp",t="/projects/xArm1s/en/latest/assets/image2.C2kyaVNt.webp",b="/projects/xArm1s/en/latest/assets/image3.B3TJ8yOs.webp",o="/projects/xArm1s/en/latest/assets/image4.CN8Hyswp.webp",a="/projects/xArm1s/en/latest/assets/image5.CGSleHBj.webp",w="/projects/xArm1s/en/latest/assets/image6.z483gapm.webp",f="/projects/xArm1s/en/latest/assets/image7.D8vi7d96.webp",v="/projects/xArm1s/en/latest/assets/image8.CS8Tc1k6.webp",y="/projects/xArm1s/en/latest/assets/image9.2uy-Pc-i.webp",x="/projects/xArm1s/en/latest/assets/image10.C4LZPbn2.webp",A="/projects/xArm1s/en/latest/assets/image1.ByU5f_d0.webp",i="/projects/xArm1s/en/latest/assets/image2.CR5I9i-v.webp",_="/projects/xArm1s/en/latest/assets/image3.Bps1-wIR.webp",S="data:image/png;base64,",B=JSON.parse('{"title":"1.xArm 1S Assembly and Degubbing","description":"","frontmatter":{},"headers":[],"relativePath":"docs/1. xArm 1S Assembly and Degubbing.md","filePath":"docs/1. xArm 1S Assembly and Degubbing.md"}'),k={name:"docs/1. xArm 1S Assembly and Degubbing.md"};function P(j,e,q,T,C,I){return s(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="_1-xarm-1s-assembly-and-degubbing" tabindex="-1">1.xArm 1S Assembly and Degubbing <a class="header-anchor" href="#_1-xarm-1s-assembly-and-degubbing" aria-label="Permalink to &quot;1.xArm 1S Assembly and Degubbing&quot;">​</a></h1><h2 id="_1-1-xarm-1s-robotic-arm" tabindex="-1">1.1 xArm 1S Robotic Arm <a class="header-anchor" href="#_1-1-xarm-1s-robotic-arm" aria-label="Permalink to &quot;1.1 xArm 1S Robotic Arm&quot;">​</a></h2><h3 id="_1-1-1-introduction" tabindex="-1">1.1.1 Introduction <a class="header-anchor" href="#_1-1-1-introduction" aria-label="Permalink to &quot;1.1.1 Introduction&quot;">​</a></h3><p>xArm 1S 6DOF robotic arm for your desktop, which has the functions of gripping, sorting, and so on. In addition, xArm 1S uses intelligent bus servos which have equipped with position feedback, voltage feedback functions for powerful and long service life.</p><p>xArm 1S supports wireless handle control, smartphone APP, and mouse control. A detailed and abundant tutorial will be provided. You can program the actions with APP or PC software to create more brilliant games.</p><img loading="lazy" height="556" width="693" class="common_img" src="'+l+'" style="width:800px;"><h3 id="_1-1-2-tutorial-learning-steps" tabindex="-1">1.1.2 Tutorial Learning Steps <a class="header-anchor" href="#_1-1-2-tutorial-learning-steps" aria-label="Permalink to &quot;1.1.2 Tutorial Learning Steps&quot;">​</a></h3><p><strong>Step 1: xArm 1S Overview</strong></p><p>There are six lessons in the chapter 1, which include introduction, assembly, debugging, and action group download. If you purchase the assembled xArm 1S, please visit Lesson 1 and Lesson 6.</p><p><strong>Step 2: Remote Control Learning</strong></p><p>Wireless handle controller, mobile APP, and mouse control are introduced in the folder 2 Remote Control Learning.</p><p><strong>Step 3: PC Software and APP Learning</strong></p><p>With the learning in this chapter, you will have a knowledge of PC software and how to program actions. Your programmed actions can be operated with the APP or performed under the offline running mode.</p><p><strong>Step 4: Manual &amp; Mobile APP Programming</strong></p><p>How to program your own action groups through Manual button programming and smartphone APP will be shown in detail in the folder of “<strong>Manual &amp;Mobile APP Programming</strong>”.</p><h3 id="_1-1-3-packing-list" tabindex="-1">1.1.3 Packing List <a class="header-anchor" href="#_1-1-3-packing-list" aria-label="Permalink to &quot;1.1.3 Packing List&quot;">​</a></h3><img loading="lazy" height="504" width="661" class="common_img" src="'+h+'" style="width:800px;"><h2 id="_1-2-bus-servo-learning" tabindex="-1">1.2 Bus Servo Learning <a class="header-anchor" href="#_1-2-bus-servo-learning" aria-label="Permalink to &quot;1.2 Bus Servo Learning&quot;">​</a></h2><h3 id="_1-2-1-bus-servo-instruction" tabindex="-1">1.2.1 Bus Servo Instruction <a class="header-anchor" href="#_1-2-1-bus-servo-instruction" aria-label="Permalink to &quot;1.2.1 Bus Servo Instruction&quot;">​</a></h3><p>The serial bus servo is based on a digital servo but is different from the PWM digital servo. It communicates through the asynchronous serial bus mode, which is controlled by sending and receiving of the command packet. It is a closed loop Control form. Based on this feature, the bus servos can be connected in series with each other. The wiring is simple and reduces the occupation of the serial port. Therefore, we need to set an ID number for each servo to send the command to a specific servo.</p><p>The built-in high-precision potentiometer not only has the ability to feed back position, temperature, voltage, and other information, but also has high accuracy and linearity. These features make the robot run more stably and extend the service life of the servo.</p><p>It’s required to set the servo to the middle position before assembly. The middle position is the initial zero point for positive and negative rotation. When the servo is rotating, the rotating part drives the potentiometer to rotate. The software will assume that the neutral position is the &quot;<strong>initial point</strong>&quot;, otherwise the potentiometer may enter the &quot;<strong>blind zone</strong>&quot;, causing the entire assembly to fail to operate normally.</p><p>ID number and middle position have been set for all the servos of xArm 1S before shipping. All of them are ready to use.</p><h3 id="_1-2-2-xarm-1s-servo" tabindex="-1">1.2.2 xArm 1S Servo <a class="header-anchor" href="#_1-2-2-xarm-1s-servo" aria-label="Permalink to &quot;1.2.2 xArm 1S Servo&quot;">​</a></h3><img loading="lazy" height="759" width="406" class="common_img" src="'+c+'" style="width:300px;"><table><colgroup><col style="width:15%;"><col style="width:18%;"><col style="width:24%;"><col style="width:20%;"><col style="width:20%;"></colgroup><thead><tr><td style="text-align:center;">Servo ID</td><td style="text-align:center;">Type</td><td style="text-align:center;">Location</td><td style="text-align:center;">Assembly</td><td style="text-align:center;">Note</td></tr></thead><tbody><tr><td style="text-align:center;">1</td><td style="text-align:center;">Servo for gripper</td><td style="text-align:center;">Gripper</td><td style="text-align:center;">Assembled servo wire</td><td style="text-align:center;">-</td></tr><tr><td style="text-align:center;">2</td><td rowspan="3" style="text-align:center;">LX-15D</td><td style="text-align:center;">Wrist</td><td style="text-align:center;">Need to install the main servo horn but not the auxiliary horn</td><td style="text-align:center;">Limit angle is 240°</td></tr><tr><td style="text-align:center;">3</td><td rowspan="3" style="text-align:center;">Body</td><td rowspan="3" style="text-align:center;">Assembled main and auxiliary horns</td><td rowspan="3" style="text-align:center;">-</td></tr><tr><td style="text-align:center;">4</td></tr><tr><td style="text-align:center;">5</td><td style="text-align:center;">LX-225</td></tr><tr><td style="text-align:center;">6</td><td style="text-align:center;">LX-15D</td><td style="text-align:center;">Bottom</td><td style="text-align:center;">Assembled main and no need for auxiliary horn</td><td style="text-align:center;">Limit angle is 320°</td></tr></tbody></table><h3 id="_1-2-3-servo-parameters" tabindex="-1">1.2.3 Servo parameters <a class="header-anchor" href="#_1-2-3-servo-parameters" aria-label="Permalink to &quot;1.2.3 Servo parameters&quot;">​</a></h3><table><colgroup><col style="width:33%;"><col style="width:19%;"><col style="width:46%;"></colgroup><thead><tr><td rowspan="14" style="text-align:center;"><img loading="lazy" height="317" width="285" class="common_img" src="'+m+'" style="width:300px;"></td><td>Attribute</td><td>Parameter</td></tr><tr><td>Size:</td><td>44.02 x 22.92 x 35.12mm</td></tr><tr><td>Gear material：</td><td>Alloy gear</td></tr><tr><td>Connector type:</td><td>PH2.0- 3P</td></tr><tr><td>Voltage：</td><td>6-8.4V</td></tr><tr><td>Torque：</td><td>15kg.cm 6V 17kg.cm 7.4V</td></tr><tr><td>Rotation：</td><td>0°-240°</td></tr><tr><td>Speed：</td><td>0.23sec/60° 7.4V</td></tr><tr><td>Control method:</td><td>UART serial command</td></tr><tr><td>Communication baud rate：</td><td>115200</td></tr><tr><td>Data feedback：</td><td>Temperature, voltage, position</td></tr><tr><td>Indicator：</td><td>RGB light</td></tr><tr><td>Store：</td><td>Save user settings when power off</td></tr><tr><td>No-load current：</td><td>100mA</td></tr></thead><tbody><tr><td rowspan="14" style="text-align:center;"><img loading="lazy" height="406" width="400" class="common_img" src="'+g+'" style="width:300px;"></td><td>Attribute</td><td>Parameter</td></tr><tr><td>Size：</td><td>40 x 20.14 x 51.1mm</td></tr><tr><td>Gear material：</td><td>Alloy gear</td></tr><tr><td>Connector type:</td><td>PH2.0- 3P</td></tr><tr><td>Voltage：</td><td>6-8.4V</td></tr><tr><td>Torque：</td><td>25kg.cm 7.4V</td></tr><tr><td>Rotation：</td><td>0°-240°</td></tr><tr><td>Speed：</td><td>0.22sec/60° 7.4V</td></tr><tr><td>Control method:</td><td>UART serial command</td></tr><tr><td>Communication baud rate：</td><td>115200</td></tr><tr><td>Data feedback：</td><td>Temperature, voltage, position</td></tr><tr><td>Indicator：</td><td>RGB light</td></tr><tr><td>Store：</td><td>Save user settings when power off</td></tr><tr><td>No-load current：</td><td>100mA</td></tr></tbody></table><h2 id="_1-4-start-xarm-1s" tabindex="-1">1.4 Start xArm 1S <a class="header-anchor" href="#_1-4-start-xarm-1s" aria-label="Permalink to &quot;1.4 Start xArm 1S&quot;">​</a></h2><ol><li><strong>Getting Ready</strong></li></ol><h3 id="_1-4-1-vacuum-pad-installation" tabindex="-1">1.4.1 Vacuum Pad Installation <a class="header-anchor" href="#_1-4-1-vacuum-pad-installation" aria-label="Permalink to &quot;1.4.1 Vacuum Pad Installation&quot;">​</a></h3><ol><li>Take out the suction cup and buckle into the four holes of the base one by one, as shown in the figure below：</li></ol><img loading="lazy" height="639" width="796" class="common_img" src="'+p+'" style="width:500px;"><ol start="2"><li>Then tighten the nut.</li></ol><h3 id="_1-4-2-adapter-connector" tabindex="-1">1.4.2 Adapter Connector <a class="header-anchor" href="#_1-4-2-adapter-connector" aria-label="Permalink to &quot;1.4.2 Adapter Connector&quot;">​</a></h3><p>Plug the power pair wiring directly into the DC power interface of the controller. Turn on the switch after connecting the power.</p><p><strong>Note:</strong> There is a low-voltage (less than 6.4V) alarm protection for the servo controller. If the power supply for the USB interface is 5V, it will make the sound of a “<strong>beep</strong>” alarm. Please use the provided adapter for the power supply.</p><ol start="2"><li><strong>Start Robotic Arm</strong></li></ol><p>The servo indicator will flash in colors to represent the normal working state after switching on the robotic arm. The LED1 of power and LED2 of signal on the controller will remain on.</p><h2 id="_1-5-adjust-deviation" tabindex="-1">1.5 Adjust Deviation <a class="header-anchor" href="#_1-5-adjust-deviation" aria-label="Permalink to &quot;1.5 Adjust Deviation&quot;">​</a></h2><h3 id="_1-5-1-whether-the-deviation-needs-to-be-adjusted" tabindex="-1">1.5.1 Whether the deviation needs to be adjusted <a class="header-anchor" href="#_1-5-1-whether-the-deviation-needs-to-be-adjusted" aria-label="Permalink to &quot;1.5.1 Whether the deviation needs to be adjusted&quot;">​</a></h3><p>The robotic arm may have a small deviation after assembly. Please check it through the following steps to decide whether to adjust the deviation.</p><p><strong>Step 1:</strong> Click “<strong>5.Appendix</strong>” to install the PC software and turn on it.</p><p><strong>Step 2:</strong> Click the “<strong>Reset Servo</strong>” button on the PC software. If the robotic arm is facing upwards and the servo main shaft brackets are parallel to each other, there is no need to adjust the deviation. As shown below:</p><img loading="lazy" height="1075" width="1910" class="common_img" src="'+u+'" style="width:800px;"><p>For example, you need to adjust the deviation if the stance as below.</p><img loading="lazy" height="1080" width="1920" class="common_img" src="'+t+'" style="width:800px;"><h3 id="_1-5-2-why-is-there-a-deviation" tabindex="-1">1.5.2 Why is there a deviation <a class="header-anchor" href="#_1-5-2-why-is-there-a-deviation" aria-label="Permalink to &quot;1.5.2 Why is there a deviation&quot;">​</a></h3><p>The deviation usually occurs in the following situations:</p><ol><li>When the servo is in the middle position, the servo&#39;s main shaft angle is rotated when the servo horn is installed, resulting in an angular deviation in the initial position.</li></ol><p>(The default servo angle is the middle position)</p><ol start="2"><li>When the servo is installed with the servo horn, the main shaft angle is not rotated, but there is a small deviation in the direction or angle of the fixed to the bracket, resulting in a slight deviation.</li></ol><p>Note that if the deviation is not adjusted, it may cause the robotic arm’s movement to be restricted, which will affect some sports effects.</p><p>In addition, the deviation value is within 100 (within an angle of 30°), which belongs to the normal adjustable range. If the deviation is large, exceeding 100, it will not be able to be adjusted by the software. You need to remove the main shaft screw of the servo with large deviation, rotate it to the vertical attitude and install it again.</p><img loading="lazy" height="646" width="969" class="common_img" src="'+b+'" style="width:500px;"><img loading="lazy" height="767" width="1150" class="common_img" src="'+o+'" style="width:500px;"><h3 id="_1-5-3-the-standard-of-deviation-adjustment" tabindex="-1">1.5.3 The standard of deviation adjustment <a class="header-anchor" href="#_1-5-3-the-standard-of-deviation-adjustment" aria-label="Permalink to &quot;1.5.3 The standard of deviation adjustment&quot;">​</a></h3><ol><li>After the robotic arm is powered on and reset, the servo main shaft bracket must be parallel; that is, the screws in the vertical direction of the bracket where the servo is located should be in the same straight line.</li></ol><img loading="lazy" height="1080" width="1920" class="common_img" src="'+a+'" style="width:500px;"><ol start="2"><li>When the robotic arm is placed, as shown in the figure below, close to the No.5 servo main shaft’s inner ring screw should be kept in the middle of the two adjacent screws in the outer ring.</li></ol><img loading="lazy" height="990" width="1760" class="common_img" src="'+w+'" style="width:500px;"><h3 id="_1-5-4-how-to-adjust" tabindex="-1">1.5.4 How to adjust <a class="header-anchor" href="#_1-5-4-how-to-adjust" aria-label="Permalink to &quot;1.5.4 How to adjust&quot;">​</a></h3><h3 id="_1-5-5-small-deviation-adjustment" tabindex="-1">1.5.5 Small deviation adjustment <a class="header-anchor" href="#_1-5-5-small-deviation-adjustment" aria-label="Permalink to &quot;1.5.5 Small deviation adjustment&quot;">​</a></h3><p>Small deviation means that the deviation value is less than 100 (the deviation angle is less than 30°). This lesson take the following picture as an example to adjust (“<strong>Servo Reset</strong>” operation has been performed)</p><img loading="lazy" height="1080" width="1920" class="common_img" src="'+t+'" style="width:800px;"><p><strong>Step1:</strong> Observe the attitude of the servo at each position of the robotic arm. It can be seen that only the No.3 servo deviation value needs to be adjusted.</p><p><strong>Step2:</strong> Click “<strong>Read Deviation</strong>” and click &quot;<strong>Continue</strong>&quot; button in the deviation prompt that pops up.</p><img loading="lazy" height="760" width="1260" class="common_img" src="'+f+'" style="width:800px;"><img loading="lazy" height="645" width="545" class="common_img" src="'+v+'" style="width:500px;"><p><strong>Step 3:</strong> Click the ID 3 servo deviation adjustment area, and drag the slider to make the ID3 servo bracket and the ID4 bracket screws direction the the same line.</p><p>Hold down the mouse and click the slider multiple times with the left button</p><img loading="lazy" height="647" width="539" class="common_img" src="'+y+'" style="width:500px;"><p><strong>Step4:</strong> After adjustment, click “<strong>Download deviation</strong>” to save the deviation to the controller.</p><p><strong>Step5:</strong> Click “<strong>Servo Reset</strong>” again and observe whether the robotic arm deviation adjustment is consistent with the 3. The target of deviation adjustment. If they are consistent, it means the deviation has been successfully adjusted. If they are inconsistent, return to step 1 and then follow the step to make fine adjustments.</p><h3 id="_1-5-6-large-deviation-adjustment" tabindex="-1">1.5.6 Large deviation adjustment <a class="header-anchor" href="#_1-5-6-large-deviation-adjustment" aria-label="Permalink to &quot;1.5.6 Large deviation adjustment&quot;">​</a></h3><p>Large deviation means that the deviation value is greater than 100 ( the deviation angle is greater than 30°). This lesson takes the following picture as an example to adjust (“<strong>Servo Reset</strong>” operation has been performed)</p><img loading="lazy" height="1080" width="1920" class="common_img" src="'+t+'" style="width:800px;"><p><strong>Step1:</strong> Observe the attitude of the servo at each position of the robotic arm. If No.3 servo has a large deviation, it needs to be reinstalled once.</p><p><strong>Step 2:</strong> Remove the main servo horn screw of the No.3 servo, and slightly open the servo bracket to separate the servo main shaft from the bracket.</p><p>Note: When you move the bracket, do not exert too much force to avoid bracket deformation.</p><img loading="lazy" height="767" width="1150" class="common_img" src="'+x+'" style="width:500px;"><p><strong>Step 3:</strong> Rotate the No.3 servo bracket so that the No.3 servo screws are in the same line as the screw on the No.4 and No.5 servo bracket below, and stop turning.</p><img loading="lazy" height="1080" width="1920" class="common_img" src="'+a+'" style="width:500px;"><p><strong>Step4:</strong> Install the bracket back to the No.3 servo main shaft and tighten the screws.</p><img loading="lazy" height="767" width="1150" class="common_img" src="'+o+'" style="width:500px;"><p><strong>Step5:</strong> Click “<strong>Servo Reset</strong>” and observe whether the robotic arm deviation adjustment is consistent with the 3.The target of deviation adjustment. If they are consistent, it means the deviation has been successfully adjusted. If there is a small deviation, then follow the 4.1 Small deviation adjustment method to make adjustments.</p><h2 id="_1-6-action-group-download" tabindex="-1">1.6 Action Group Download <a class="header-anchor" href="#_1-6-action-group-download" aria-label="Permalink to &quot;1.6 Action Group Download&quot;">​</a></h2><h3 id="_1-6-1-preface" tabindex="-1">1.6.1 Preface <a class="header-anchor" href="#_1-6-1-preface" aria-label="Permalink to &quot;1.6.1 Preface&quot;">​</a></h3><p>The robot arm is like a human arm, the limbs need &quot;<strong>muscle memory</strong>&quot; to perform their move function. Therefore, the action group needs to be downloaded to the controller to perform the action.</p><h3 id="_1-6-2-download-method" tabindex="-1">1.6.2 Download Method <a class="header-anchor" href="#_1-6-2-download-method" aria-label="Permalink to &quot;1.6.2 Download Method&quot;">​</a></h3><ol><li><p>Connect robot arm and computer, and turn on PC software.</p></li><li><p>Click &quot;<strong>Servo Test</strong> &quot;to switch debug mode on PC interface.</p></li></ol><img loading="lazy" height="760" width="1260" class="common_img" src="'+A+'" style="width:800px;"><ol start="3"><li>Click &quot;<strong>Mass download</strong> &quot; button, and select &quot;<strong>Action Group</strong> &quot;file in the pop-up prompt file.</li></ol><img loading="lazy" height="760" width="1260" class="common_img" src="'+i+'" style="width:800px;"><ol start="4"><li>Open the file and select (From No.0- Initial Action to No.11-Omin-directional Rotational Detection Grip) all action groups. Then click &quot;<strong>Open</strong>&quot; button.</li></ol><img loading="lazy" height="760" width="1260" class="common_img" src="'+i+'" style="width:800px;"><ol start="5"><li>Wait for a while, after all the action groups are added, the imported action group serial number will be displayed in the list, and then click the &quot;<strong>Mass download</strong>&quot; button.</li></ol><img loading="lazy" height="234" width="313" class="common_img" src="'+_+'" style="width:300px;"><ol start="6"><li>Next, the &quot;<strong>Mass download</strong>&quot; button will appear download progress prompt. Each time a file is successfully download. The robot arm will emit a &quot;<strong>beep</strong>&quot; sound reminder. After waiting for the download progress prompt to disappear, all files are download to the controller.</li></ol><img loading="lazy" height="128" width="141" class="common_img" src="'+S+'" style="width:300px;">',100)])])}const D=r(k,[["render",P]]);export{B as __pageData,D as default};
